import{c as e,i as t,o as n,r,s as i,t as a}from"./app-CSY-Kgjv.js";var o=JSON.parse(`{"path":"/ai/ml/","title":"机器学习","lang":"zh-CN","frontmatter":{"description":"机器学习 DeeLMind 提示 算法学习网站 MathPH 什么是机器学习 机器学习是人工智能的一个分支。人工智能的研究历史有着一条从以“推理”为重点，到以“知识”为重点，再到以“学习”为重点的自然、清晰的脉络。显然，机器学习是实现人工智能的一个途径之一，即以机器学习为手段，解决人工智能中的部分问题。机器学习在近 30 多年已发展为一门多领域科际整合...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"机器学习\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-10-02T01:54:36.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/ai/ml/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"机器学习"}],["meta",{"property":"og:description","content":"机器学习 DeeLMind 提示 算法学习网站 MathPH 什么是机器学习 机器学习是人工智能的一个分支。人工智能的研究历史有着一条从以“推理”为重点，到以“知识”为重点，再到以“学习”为重点的自然、清晰的脉络。显然，机器学习是实现人工智能的一个途径之一，即以机器学习为手段，解决人工智能中的部分问题。机器学习在近 30 多年已发展为一门多领域科际整合..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-02T01:54:36.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-02T01:54:36.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1790906076000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":3,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":2.77,"words":832},"filePathRelative":"ai/ml/README.md","autoDesc":true}`),s={name:`README.md`};function c(a,o,s,c,l,u){let d=e(`DocsAD`);return i(),r(`div`,null,[o[0]||=t(`<h1 id="机器学习" tabindex="-1"><a class="header-anchor" href="#机器学习"><span>机器学习</span></a></h1><div class="hint-container warning"><p class="hint-container-title">DeeLMind 提示</p><p><a href="https://deelmind.com/mathph/" target="_blank" rel="noopener noreferrer">算法学习网站 MathPH</a></p></div><h2 id="什么是机器学习" tabindex="-1"><a class="header-anchor" href="#什么是机器学习"><span>什么是机器学习</span></a></h2><p>机器学习是人工智能的一个分支。人工智能的研究历史有着一条从以“推理”为重点，到以“知识”为重点，再到以“学习”为重点的自然、清晰的脉络。显然，机器学习是实现人工智能的一个途径之一，即以机器学习为手段，解决人工智能中的部分问题。机器学习在近 30 多年已发展为一门多领域科际整合，涉及概率论、统计学、逼近论、凸分析、计算复杂性理论等多门学科。</p><h2 id="机器学习类型" tabindex="-1"><a class="header-anchor" href="#机器学习类型"><span>机器学习类型</span></a></h2><ul><li>分类(Classification)</li><li>回归(Regression)(预测)</li></ul>`,6),n(d),o[1]||=t(`<h1 id="机器学习主流算法" tabindex="-1"><a class="header-anchor" href="#机器学习主流算法"><span>机器学习主流算法</span></a></h1><h2 id="监督学习" tabindex="-1"><a class="header-anchor" href="#监督学习"><span>监督学习</span></a></h2><h3 id="_1-线性回归-linear-regression" tabindex="-1"><a class="header-anchor" href="#_1-线性回归-linear-regression"><span>1. 线性回归 (Linear Regression)</span></a></h3><ul><li>描述：通过线性关系建模，用于预测连续值。</li><li>应用：房价预测、销售预测等。</li></ul><h3 id="_2-支持向量机-support-vector-machines-svm" tabindex="-1"><a class="header-anchor" href="#_2-支持向量机-support-vector-machines-svm"><span>2. 支持向量机 (Support Vector Machines, SVM)</span></a></h3><ul><li>描述：寻找一个决策边界，使得样本点离该边界最远，用于分类和回归。</li><li>应用：图像分类、文本分类等。</li></ul><h3 id="_3-决策树-decision-trees" tabindex="-1"><a class="header-anchor" href="#_3-决策树-decision-trees"><span>3. 决策树 (Decision Trees)</span></a></h3><ul><li>描述：基于树状结构进行决策，通过对特征的递归分割来进行分类。</li><li>应用：医学诊断、金融风险评估等。</li></ul><h3 id="_4-随机森林-random-forest" tabindex="-1"><a class="header-anchor" href="#_4-随机森林-random-forest"><span>4. 随机森林 (Random Forest)</span></a></h3><ul><li>描述：集成学习方法，由多个决策树组成，通过投票进行分类或回归。</li><li>应用：图像识别、信用评分等。</li></ul><h3 id="_5-k-近邻算法-k-nearest-neighbors-knn" tabindex="-1"><a class="header-anchor" href="#_5-k-近邻算法-k-nearest-neighbors-knn"><span>5. K 近邻算法 (K-Nearest Neighbors, KNN)</span></a></h3><ul><li>描述：根据邻近样本进行分类，即样本的类别由其最近邻居的多数类别决定。</li><li>应用：手写数字识别、推荐系统等。</li></ul><h3 id="_6-朴素贝叶斯-naive-bayes" tabindex="-1"><a class="header-anchor" href="#_6-朴素贝叶斯-naive-bayes"><span>6. 朴素贝叶斯 (Naive Bayes)</span></a></h3><ul><li>描述：基于贝叶斯定理，假设特征之间相互独立，用于分类问题。</li><li>应用：垃圾邮件过滤、情感分析等。</li></ul><h3 id="_7-神经网络-neural-networks" tabindex="-1"><a class="header-anchor" href="#_7-神经网络-neural-networks"><span>7. 神经网络 (Neural Networks)</span></a></h3><ul><li>描述：通过多层神经元组成的网络进行学习，用于复杂模式识别。</li><li>应用：图像识别、语音识别等。</li></ul><h2 id="无监督学习" tabindex="-1"><a class="header-anchor" href="#无监督学习"><span>无监督学习</span></a></h2><h3 id="_1-k-均值聚类-k-means-clustering" tabindex="-1"><a class="header-anchor" href="#_1-k-均值聚类-k-means-clustering"><span>1. K 均值聚类 (K-Means Clustering)</span></a></h3><ul><li>描述：将样本分为 K 个簇，使得每个样本都属于离它最近的簇。</li><li>应用：图像分割、客户分群等。</li></ul><h3 id="_2-层次聚类-hierarchical-clustering" tabindex="-1"><a class="header-anchor" href="#_2-层次聚类-hierarchical-clustering"><span>2. 层次聚类 (Hierarchical Clustering)</span></a></h3><ul><li>描述：通过构建树形结构进行聚类，直到所有样本都属于一个簇。</li><li>应用：生物学分类、文档聚类等。</li></ul><h3 id="_3-主成分分析-principal-component-analysis-pca" tabindex="-1"><a class="header-anchor" href="#_3-主成分分析-principal-component-analysis-pca"><span>3. 主成分分析 (Principal Component Analysis, PCA)</span></a></h3><ul><li>描述：降维技术，通过找到数据中的主要成分来减少维度。</li><li>应用：数据可视化、特征提取等。</li></ul><h3 id="_4-t-分布邻域嵌入-t-distributed-stochastic-neighbor-embedding-t-sne" tabindex="-1"><a class="header-anchor" href="#_4-t-分布邻域嵌入-t-distributed-stochastic-neighbor-embedding-t-sne"><span>4. t-分布邻域嵌入 (t-Distributed Stochastic Neighbor Embedding, t-SNE)</span></a></h3><ul><li>描述：降维方法，用于可视化高维数据。</li><li>应用：可视化聚类结果、图像嵌入等。</li></ul><h3 id="_5-自编码器-autoencoder" tabindex="-1"><a class="header-anchor" href="#_5-自编码器-autoencoder"><span>5. 自编码器 (Autoencoder)</span></a></h3><ul><li>描述：通过学习数据的压缩表示，用于降维和特征学习。</li><li>应用：异常检测、图像去噪等。</li></ul><h3 id="_6-关联规则学习-association-rule-learning" tabindex="-1"><a class="header-anchor" href="#_6-关联规则学习-association-rule-learning"><span>6. 关联规则学习 (Association Rule Learning)</span></a></h3><ul><li>描述：发现数据中的关联规则，如频繁出现的项集。</li><li>应用：购物篮分析、交叉销售推荐等。</li></ul><h3 id="_7-高斯混合模型-gaussian-mixture-model-gmm" tabindex="-1"><a class="header-anchor" href="#_7-高斯混合模型-gaussian-mixture-model-gmm"><span>7. 高斯混合模型 (Gaussian Mixture Model, GMM)</span></a></h3><ul><li>描述：假设数据是由多个高斯分布混合而成，用于密度估计和聚类。</li><li>应用：图像分割、异常检测等。</li></ul>`,31)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};